  "open-commitments": {
    "recipe_id": "open-commitments",
    "chat_exposed": true,
    "version": 1,
    "ttl": 60,
    "metadata": {
      "name": "Open commitments",
      "description": "Use “Open commitments” in Recued. Dashboard of open commitments and tasks per contact and project, sorted by each contact's follow-through reliability — dependable counterparties land on top so the easy wins get chased first. Auto-refreshes weekday morning and early afternoon; invoke any time for the current view.",
      "author": "recued-core",
      "supported_platforms": [],
      "tags": [
        "productivity",
        "commitment",
        "open-loop",
        "dashboard",
        "ai_surface",
        "reactive",
        "pack:personal-organizer"
      ],
      "budget_ms": 30000
    },
    "variables": {
      "open_loop_limit": {
        "label": "Max open-loop entries to surface",
        "type": "number",
        "default": 10
      },
      "start_hour": {
        "label": "Window start hour (local TZ)",
        "type": "number",
        "default": 8
      },
      "end_hour": {
        "label": "Window end hour (local TZ)",
        "type": "number",
        "default": 18
      }
    },
    "requires": [],
    "auto_run": {
      "interval_ms": 600000
    },
    "trigger_steps": [
      {
        "id": "active_window",
        "op": "core.watch.time",
        "args": {
          "weekdays": [
            1,
            2,
            3,
            4,
            5
          ],
          "start_hour": "{{config.start_hour}}",
          "end_hour": "{{config.end_hour}}"
        }
      }
    ],
    "prefetch_steps": [
      {
        "id": "open_loops",
        "op": "core.data.enrichment.list",
        "args": {
          "topic": "open_loop_pressure",
          "scope": "contact",
          "limit": "{{config.open_loop_limit}}"
        }
      },
      {
        "id": "reliability_bands",
        "op": "core.data.enrichment.list",
        "args": {
          "topic": "commitment_reliability_band",
          "scope": "contact",
          "limit": "{{config.open_loop_limit}}"
        }
      }
    ],
    "steps": [
      {
        "id": "open_loop_count",
        "transform": "count",
        "input": "{{step.open_loops.entries}}"
      },
      {
        "id": "reliability_count",
        "transform": "count",
        "input": "{{step.reliability_bands.entries}}"
      },
      {
        "id": "open_loop_targets",
        "transform": "pluck",
        "array": "{{step.open_loops.entries}}",
        "field": "target_id"
      },
      {
        "id": "open_loop_text",
        "transform": "join",
        "array": "{{step.open_loop_targets}}",
        "separator": ", "
      },
      {
        "id": "high_reliability",
        "transform": "filter",
        "array": "{{step.reliability_bands.entries}}",
        "field": "value.band",
        "operator": "equal",
        "value": "high"
      },
      {
        "id": "mid_reliability",
        "transform": "filter",
        "array": "{{step.reliability_bands.entries}}",
        "field": "value.band",
        "operator": "equal",
        "value": "mid"
      },
      {
        "id": "low_reliability",
        "transform": "filter",
        "array": "{{step.reliability_bands.entries}}",
        "field": "value.band",
        "operator": "equal",
        "value": "low"
      },
      {
        "id": "high_reliability_targets",
        "transform": "pluck",
        "array": "{{step.high_reliability}}",
        "field": "target_id"
      },
      {
        "id": "mid_reliability_targets",
        "transform": "pluck",
        "array": "{{step.mid_reliability}}",
        "field": "target_id"
      },
      {
        "id": "low_reliability_targets",
        "transform": "pluck",
        "array": "{{step.low_reliability}}",
        "field": "target_id"
      },
      {
        "id": "high_reliability_text",
        "transform": "join",
        "array": "{{step.high_reliability_targets}}",
        "separator": ", "
      },
      {
        "id": "mid_reliability_text",
        "transform": "join",
        "array": "{{step.mid_reliability_targets}}",
        "separator": ", "
      },
      {
        "id": "low_reliability_text",
        "transform": "join",
        "array": "{{step.low_reliability_targets}}",
        "separator": ", "
      },
      {
        "id": "card",
        "transform": "to_summary",
        "fields": [
          {
            "label": "Open-loop contacts",
            "value": "{{step.open_loop_count:number}}"
          },
          {
            "label": "Reliability rows scanned",
            "value": "{{step.reliability_count:number}}"
          },
          {
            "label": "High-reliability follow-ups (chase first)",
            "value": "{{step.high_reliability_text}}"
          },
          {
            "label": "Mid-reliability follow-ups (standard chase)",
            "value": "{{step.mid_reliability_text}}"
          },
          {
            "label": "Low-reliability follow-ups (long-tail)",
            "value": "{{step.low_reliability_text}}"
          },
          {
            "label": "All open-loop targets",
            "value": "{{step.open_loop_text}}"
          }
        ]
      }
    ],
    "output": {
      "render": [
        {
          "type": "summary",
          "source": "step.card"
        }
      ]
    }
  },
  "recent-notes-by-topic": {
    "recipe_id": "recent-notes-by-topic",
    "chat_exposed": true,
    "version": 1,
    "ttl": 60,
    "metadata": {
      "name": "Recent notes by topic",
      "description": "Use “Recent notes by topic” in Recued. Surface your still-warm notes: ranks notes by ongoing relevance (recently touched and frequently referenced rise; dormant ones decay over 180 days) and shows the freshest decile. Private notes stay private by default.",
      "author": "recued-core",
      "supported_platforms": [],
      "tags": [
        "productivity",
        "note",
        "recent",
        "dashboard",
        "ai_surface",
        "reactive",
        "pack:personal-organizer"
      ],
      "budget_ms": 30000
    },
    "variables": {
      "note_limit": {
        "label": "Max recent-notes entries to surface",
        "type": "number",
        "default": 10
      }
    },
    "requires": [],
    "auto_run": {
      "interval_ms": 600000
    },
    "trigger_steps": [
      {
        "id": "morning_window",
        "op": "core.watch.time",
        "args": {
          "weekdays": [
            1,
            2,
            3,
            4,
            5
          ],
          "start_hour": 8,
          "end_hour": 9
        }
      }
    ],
    "prefetch_steps": [
      {
        "id": "relevance_rows",
        "op": "core.data.enrichment.list",
        "args": {
          "topic": "note_relevance_decay",
          "scope": "note",
          "limit": "{{config.note_limit}}"
        }
      }
    ],
    "steps": [
      {
        "id": "row_count",
        "transform": "count",
        "input": "{{step.relevance_rows.entries}}"
      },
      {
        "id": "note_ids",
        "transform": "pluck",
        "array": "{{step.relevance_rows.entries}}",
        "field": "target_id"
      },
      {
        "id": "note_ids_text",
        "transform": "join",
        "array": "{{step.note_ids}}",
        "separator": ", "
      },
      {
        "id": "defaults",
        "transform": "defaults",
        "fields": {
          "first_note_id": {
            "value": "{{step.relevance_rows.entries.0.target_id}}",
            "fallback": ""
          },
          "first_relevance_score": {
            "value": "{{step.relevance_rows.entries.0.value.relevance_score}}",
            "fallback": 0
          }
        }
      },
      {
        "id": "card",
        "transform": "to_summary",
        "fields": [
          {
            "label": "Recent notes (relevance-ranked)",
            "value": "{{step.row_count:number}}"
          },
          {
            "label": "Top note ID",
            "value": "{{step.first_note_id}}"
          },
          {
            "label": "Top note relevance",
            "value": "{{step.first_relevance_score:number}}"
          },
          {
            "label": "All recent note IDs",
            "value": "{{step.note_ids_text}}"
          }
        ]
      }
    ],
    "output": {
      "render": [
        {
          "type": "summary",
          "source": "step.card"
        }
      ]
    }
  },
