  "remind-me-of": {
    "recipe_id": "remind-me-of",
    "chat_exposed": true,
    "version": 3,
    "ttl": 60,
    "metadata": {
      "name": "Remind me",
      "description": "Use “Remind me” in Recued. Set a one-time reminder: Recued tells you at that time, once, on every channel you set up. Work out the time from the current date and time in your context, on the user's clock. Pass it with its offset, and tell the user the time the answer gives.",
      "author": "recued-core",
      "supported_platforms": [],
      "tags": [
        "reminder",
        "notify",
        "personal-organizer",
        "pack:personal-organizer"
      ],
      "budget_ms": 10000
    },
    "variables": {
      "reminder_text": {
        "label": "Reminder text",
        "type": "string",
        "help": "What the reminder says when it rings, in the user's words."
      },
      "remind_at": {
        "label": "Remind at",
        "type": "datetime",
        "help": "When the reminder should ring, as an absolute ISO 8601 / RFC 3339 date-time WITH a timezone offset (e.g. 2026-07-04T15:00:00-07:00 or 2026-07-04T22:00:00Z). Resolve the user's requested time against the current date/time in your context, in the user's timezone — do NOT assume UTC; if the timezone is unknown, ask before guessing. An offset-less value is rejected, and so is a time that has passed."
      }
    },
    "requires": [
      "notification_send"
    ],
    "steps": [
      {
        "id": "due_at_ms",
        "transform": "date_parse",
        "input": "{{config.remind_at}}",
        "require_offset": true,
        "fail_on": "{{step.due_at_ms}} is_null",
        "fail_reason": "Remind at could not be read as a date and time with its offset from UTC. Enter one that includes the offset."
      },
      {
        "id": "set",
        "op": "core.reminder.create",
        "args": {
          "text": "{{config.reminder_text}}",
          "at": "{{step.due_at_ms}}"
        }
      },
      {
        "id": "card",
        "transform": "to_summary",
        "fields": [
          {
            "label": "Reminder",
            "value": "{{step.set.reminder.text}}"
          },
          {
            "label": "When",
            "value": "{{step.set.confirmation}}"
          }
        ]
      }
    ],
    "output": {
      "render": [
        {
          "type": "summary",
          "source": "step.card"
        }
      ]
    }
  },
  "reschedule-booking": {
    "recipe_id": "reschedule-booking",
    "chat_exposed": false,
    "version": 1,
    "ttl": 60,
    "requires": [],
    "metadata": {
      "name": "Reschedule a booking",
      "description": "Use “Reschedule a booking” in Recued. It carries out the named workflow using the connections and settings you choose.",
      "author": "recued-core",
      "supported_platforms": [],
      "tags": [
        "calendar",
        "reschedule",
        "booking",
        "reception",
        "notify"
      ],
      "budget_ms": 30000
    },
    "variables": {
      "booking_id": {
        "label": "Booking id",
        "type": "string",
        "default": ""
      },
      "new_start_at": {
        "label": "New start (unix ms)",
        "type": "number",
        "default": null
      },
      "new_end_at": {
        "label": "New end (unix ms)",
        "type": "number",
        "default": null
      },
      "notify_visitor": {
        "label": "Tell the visitor their booking moved",
        "type": "boolean",
        "default": false
      },
      "sender_mail_instance": {
        "label": "Send from (data.mail account)",
        "type": "string",
        "default": ""
      }
    },
    "steps": [
      {
        "id": "ready",
        "transform": "all",
        "conditions": [
          "{{config.booking_id}} is_not_empty",
          "{{config.new_start_at}} is_not_null",
          "{{config.new_end_at}} is_not_null"
        ]
      },
      {
        "id": "reschedule",
        "skip_when": "{{step.ready}} not_equal true",
        "op": "core.work-entity.booking.update",
        "args": {
          "id": "{{config.booking_id}}",
          "slot_start_at": "{{config.new_start_at}}",
          "slot_end_at": "{{config.new_end_at}}"
        }
      },
      {
        "id": "moved",
        "transform": "compare",
        "left": "{{step.reschedule.booking.id}}",
        "operator": "is_not_null"
      },
      {
        "id": "new_time",
        "transform": "date_format",
        "date": "{{config.new_start_at}}",
        "format": "YYYY-MM-DD HH:mm"
      },
      {
        "id": "notify_ready",
        "transform": "all",
        "conditions": [
          "{{config.notify_visitor}} equal true",
          "{{step.moved}} equal true",
          "{{config.sender_mail_instance}} is_not_empty"
        ]
      },
      {
        "id": "subject",
        "skip_when": "{{step.notify_ready}} not_equal true",
        "transform": "template",
        "template": "Your booking has moved to {{step.new_time}}"
      },
      {
        "id": "body",
        "skip_when": "{{step.notify_ready}} not_equal true",
        "transform": "template",
        "template": "Hi — the time for your booking has changed. It is now {{step.new_time}}. If the new time does not work for you, just reply to this message and we will sort it out."
      },
      {
        "id": "notify",
        "skip_when": "{{step.notify_ready}} not_equal true",
        "op": "core.mail.notify-booking-visitor",
        "args": {
          "booking_id": "{{config.booking_id}}",
          "sender_mail_instance": "{{config.sender_mail_instance}}",
          "subject": "{{step.subject}}",
          "body": "{{step.body}}"
        }
      },
      {
        "id": "visitor_told",
        "transform": "default",
        "value": "{{step.notify.notified}}",
        "fallback": false
      },
      {
        "id": "card",
        "transform": "to_summary",
        "fields": [
          {
            "label": "Booking",
            "value": "{{config.booking_id}}"
          },
          {
            "label": "Rescheduled",
            "value": "{{step.moved}}"
          },
          {
            "label": "New start",
            "value": "{{config.new_start_at:date}}"
          },
          {
            "label": "New end",
            "value": "{{config.new_end_at:date}}"
          },
          {
            "label": "Visitor told",
            "value": "{{step.visitor_told}}"
          }
        ]
      }
    ],
    "output": {
      "render": [
        {
          "type": "summary",
          "source": "step.card"
        }
      ]
    }
  },
