  "reschedule-calendar-event": {
    "recipe_id": "reschedule-calendar-event",
    "chat_exposed": false,
    "version": 2,
    "ttl": 60,
    "requires": [],
    "metadata": {
      "name": "Reschedule a calendar event",
      "description": "Use “Reschedule a calendar event” in Recued. It carries out the named workflow using the connections and settings you choose.",
      "author": "recued-core",
      "supported_platforms": [],
      "tags": [
        "calendar",
        "reschedule",
        "booking",
        "reception",
        "owner-action"
      ],
      "budget_ms": 20000
    },
    "variables": {
      "calendar_slug": {
        "label": "Calendar instance slug",
        "type": "string",
        "default": ""
      },
      "event_source_id": {
        "label": "Event source id",
        "type": "string",
        "default": ""
      },
      "new_start_at": {
        "label": "New start (unix ms)",
        "type": "number",
        "default": null
      },
      "new_end_at": {
        "label": "New end (unix ms)",
        "type": "number",
        "default": null
      }
    },
    "steps": [
      {
        "id": "ready",
        "transform": "all",
        "conditions": [
          "{{config.calendar_slug}} is_not_empty",
          "{{config.event_source_id}} is_not_empty",
          "{{config.new_start_at}} is_not_null",
          "{{config.new_end_at}} is_not_null"
        ]
      },
      {
        "id": "reschedule",
        "skip_when": "{{step.ready}} not_equal true",
        "op": "core.data.calendar.update",
        "args": {
          "slug": "{{config.calendar_slug}}",
          "source_id": "{{config.event_source_id}}",
          "patch": {
            "start_at": "{{config.new_start_at}}",
            "end_at": "{{config.new_end_at}}"
          }
        }
      },
      {
        "id": "moved",
        "transform": "compare",
        "left": "{{step.reschedule.source_id}}",
        "operator": "is_not_null"
      },
      {
        "id": "moved_event",
        "skip_when": "{{step.moved}} not_equal true",
        "op": "core.data.calendar.get",
        "args": {
          "slug": "{{config.calendar_slug}}",
          "source_id": "{{config.event_source_id}}"
        }
      },
      {
        "id": "new_time",
        "transform": "event_when",
        "event": {
          "start_at": "{{step.moved_event.record.start_at}}",
          "end_at": "{{step.moved_event.record.end_at}}",
          "is_all_day": "{{step.moved_event.record.is_all_day}}"
        },
        "part": "text",
        "time_zone": "{{context.server.time_zone}}"
      },
      {
        "id": "card",
        "transform": "to_summary",
        "fields": [
          {
            "label": "Event",
            "value": "{{config.event_source_id}}"
          },
          {
            "label": "Rescheduled",
            "value": "{{step.moved}}"
          },
          {
            "label": "New time",
            "value": "{{step.new_time}}"
          }
        ]
      }
    ],
    "output": {
      "render": [
        {
          "type": "summary",
          "source": "step.card"
        }
      ]
    }
  },
  "rewrite-composed-mail": {
    "recipe_id": "rewrite-composed-mail",
    "chat_exposed": false,
    "version": 1,
    "ttl": 0,
    "metadata": {
      "name": "Rewrite a composed email",
      "description": "Use “Rewrite a composed email” in Recued. Choose a formal, friendly, or polished rewrite of the message body, then review the result before sending. Recued leaves the subject, recipients, sender, attachments, and reply context unchanged, and protects known email addresses while the selected AI model works.",
      "author": "recued-core",
      "supported_platforms": [],
      "budget_ms": 30000,
      "tags": [
        "mail",
        "compose",
        "ai",
        "rewrite",
        "draft"
      ]
    },
    "variables": {
      "body": {
        "label": "Message body",
        "type": "text",
        "default": ""
      },
      "sender_email": {
        "label": "Sender address",
        "type": "string",
        "default": ""
      },
      "to": {
        "label": "To",
        "type": "array",
        "default": []
      },
      "cc": {
        "label": "Cc",
        "type": "array",
        "default": []
      },
      "bcc": {
        "label": "Bcc",
        "type": "array",
        "default": []
      },
      "style": {
        "label": "Rewrite style",
        "type": "string",
        "default": "polished"
      },
      "instructions": {
        "label": "Rewrite constraints",
        "type": "text",
        "default": "Return only the rewritten email body. Preserve meaning, factual claims, links, formatting intent, and the writer's level of detail. Do not invent names, dates, promises, prices, attachments, or a new subject line."
      }
    },
    "prefetch_steps": [],
    "steps": [
      {
        "id": "protect",
        "transform": "pii-protect",
        "data": {
          "sender_email": "{{config.sender_email}}",
          "to": "{{config.to}}",
          "cc": "{{config.cc}}",
          "bcc": "{{config.bcc}}",
          "body": "{{config.body}}"
        },
        "fields": [
          {
            "path": "sender_email",
            "kind": "email"
          },
          {
            "path": "to",
            "kind": "email"
          },
          {
            "path": "cc",
            "kind": "email"
          },
          {
            "path": "bcc",
            "kind": "email"
          },
          {
            "path": "body",
            "kind": "content"
          }
        ]
      },
      {
        "id": "rewrite",
        "op": "core.ai.rewrite",
        "args": {
          "llm.data": "{{step.protect.aliased.body}}",
          "llm.style": "{{config.style}}",
          "llm.instructions": "{{config.instructions}}",
          "llm.model_hint": "fast"
        }
      },
      {
        "id": "restore",
        "transform": "pii-restore",
        "data": "{{step.rewrite.rewritten}}",
        "ledger_handle": "{{step.protect.ledger_handle}}"
      }
    ],
    "output": {
      "render": [
        {
          "type": "text",
          "source": "step.restore.restored"
        }
      ]
    }
  },
